L13_1 = "경계심은 함부로 놓는거 아냐. 낯선 사람 앞에선 순진하게 굴지 마라."
L12_1.m_Talk_KOREA = L13_1
L12_1.m_fTalkTime = 0.03
L13_1 = "見知らぬ人の前ですぐに警戒心を解くもんじゃない。"
L12_1.m_Talk_JPN = L13_1
L13_1 = "You shouldn't let your guard down so easily. And don't act so naive in front of strangers."
L12_1.m_Talk_ENG = L13_1
L13_1 = "不能隨便放下戒心，也不要在陌生人面前表現得太天真。"
L12_1.m_Talk_TWN = L13_1
L13_1 = "警惕心不能随便放下啊。也不要在陌生人面前表现得太天真。"
L12_1.m_Talk_SCN = L13_1
L13_1 = "You shouldn't let your guard down so easily. And don't act so naive in front of strangers."
L12_1.m_Talk_DEU = L13_1
L13_1 = "You shouldn't let your guard down so easily. And don't act so naive in front of strangers."
