L20_1 = "많이 노력했던 덕분일까? 마을 사람들은 점점 나에게 따뜻하게 대해줬어."
L19_1.m_Talk_KOREA = L20_1
L19_1.m_fTalkTime = 0.03
L20_1 = "m_bTalkCenterFadeIn"
L19_1[L20_1] = true
L20_1 = "一生懸命頑張ったからなのか、村の人たちは徐々に優しく接してくれるようになった。"
L19_1.m_Talk_JPN = L20_1
L20_1 = "Was it because of all my hard work? But the village people started to open up to me."
L19_1.m_Talk_ENG = L20_1
L20_1 = "是因為我的努力嗎？村裡的人們漸漸對我熱情了起來。"
L19_1.m_Talk_TWN = L20_1
L20_1 = "是因为努力了吗？村里的人们渐渐对我热情了起来。"
L19_1.m_Talk_SCN = L20_1
L20_1 = "Was it because of all my hard work? But the village people started to open up to me."
L19_1.m_Talk_DEU = L20_1
L20_1 = "Was it because of all my hard work? But the village people started to open up to me."
L19_1.m_Talk_FRA = L20_1
L20_1 = {}
L21_1 = "DOLL_ACT3_INTERLUDE5@220#Talk"
