L20_1.m_CutScenID = 6500307
L20_1.m_CutScenStrID = "DOLL_ACT3_INTERLUDE5"
L20_1.m_bWaitClick = true
L20_1.m_fWaitTime = 0
L21_1 = "처음엔 적응하기 조금 힘들었지만… 이젠 고향과도 같은 곳이 되었지."
L20_1.m_Talk_KOREA = L21_1
L20_1.m_fTalkTime = 0.03
L21_1 = "m_bTalkCenterFadeIn"
L20_1[L21_1] = true
L21_1 = "最初は適応するのに苦労したけど……今では故郷のような場所になっていた。"
L20_1.m_Talk_JPN = L21_1
L21_1 = "It was hard to adjust to it at first... but now, this place was like home."
L20_1.m_Talk_ENG = L21_1
L21_1 = "剛開始有點難以適應……但現在已經像是家一樣的地方了。"
L20_1.m_Talk_TWN = L21_1
L21_1 = "刚开始有点难以适应……但现在已经像是家一样的地方了。"
L20_1.m_Talk_SCN = L21_1
L21_1 = "It was hard to adjust to it at first... but now, this place was like home."
L20_1.m_Talk_DEU = L21_1
L21_1 = "It was hard to adjust to it at first... but now, this place was like home."
L20_1.m_Talk_FRA = L21_1
